// Live flipbook playback for the landing page. Plays a real sprite sheet
// generated by Flipbook Maker (8x8 = 64 frames) entirely in the browser.
(function () {
  const COLS = 8, ROWS = 8, FRAMES = 64;
  const ALPHA_SRC = "assets/flipbook-fire.png";
  const OPAQUE_SRC = "assets/flipbook-fire-opaque.png";

  const canvas = document.getElementById("player");
  const ctx = canvas.getContext("2d");
  const fpsInput = document.getElementById("fps");
  const fpsVal = document.getElementById("fpsVal");
  const playBtn = document.getElementById("playBtn");
  const alphaBox = document.getElementById("alpha");
  const gridBtn = document.getElementById("gridBtn");
  const stage = canvas.parentElement;

  const imgs = {};
  let current = null;
  let fps = 30, frame = 0, last = 0, playing = true, showSheet = false;

  function load(src) {
    if (imgs[src]) { current = imgs[src]; return; }
    const im = new Image();
    im.onload = () => { imgs[src] = im; current = im; };
    im.src = src;
  }
  load(ALPHA_SRC);
  load(OPAQUE_SRC);

  function drawSheet() {
    if (!current) return;
    canvas.width = canvas.height = 512;
    ctx.clearRect(0, 0, 512, 512);
    ctx.drawImage(current, 0, 0, 512, 512);
  }

  function drawFrame() {
    if (!current) return;
    canvas.width = canvas.height = 384;
    const cw = current.naturalWidth / COLS;
    const ch = current.naturalHeight / ROWS;
    const f = frame % FRAMES;
    const sx = (f % COLS) * cw;
    const sy = Math.floor(f / COLS) * ch;
    ctx.clearRect(0, 0, 384, 384);
    ctx.drawImage(current, sx, sy, cw, ch, 0, 0, 384, 384);
  }

  function tick(now) {
    requestAnimationFrame(tick);
    if (showSheet) { drawSheet(); return; }
    if (!playing) return;
    if (now - last >= 1000 / fps) {
      last = now;
      frame = (frame + 1) % FRAMES;
      drawFrame();
    }
  }

  fpsInput.addEventListener("input", (e) => {
    fps = +e.target.value; fpsVal.textContent = e.target.value;
  });
  playBtn.addEventListener("click", () => {
    playing = !playing;
    playBtn.textContent = playing ? "⏸ Pause" : "▶ Play";
  });
  alphaBox.addEventListener("change", (e) => {
    current = imgs[e.target.checked ? ALPHA_SRC : OPAQUE_SRC] || current;
    stage.classList.toggle("checker", e.target.checked);
    if (showSheet) drawSheet();
  });
  gridBtn.addEventListener("click", () => {
    showSheet = !showSheet;
    gridBtn.textContent = showSheet ? "Show playback" : "Show sheet";
    if (!showSheet) { canvas.width = canvas.height = 384; }
  });

  requestAnimationFrame(tick);
})();
